//! Replays `testdata/port/ingest/magika.json`, generated by the real Go
//! `TestPortIngestMagikaContract`: `Detect`, `filetype.Detect` and
//! `VerifyAgainstGuess` against fake `magika` executables (the script is stored
//! in the fixture). Prediction, advisory log lines, stderr, kind and argv
//! transcript must match Go; the advisory never changes the kind.
#![cfg(unix)]

use serde::Deserialize;
use std::os::unix::fs::PermissionsExt;
use std::path::Path;
use std::sync::Mutex;
use symdesk_ingest::extract::detect_file_with;
use symdesk_ingest::filetype::{self, MagikaPrediction};

/// `PATH` is process-global; scenarios replace it one at a time.
static PATH_LOCK: Mutex<()> = Mutex::new(());

#[derive(Deserialize)]
struct Scenario {
    id: String,
    tool: String,
    stdout: String,
    stderr: String,
    exit: i32,
    file: String,
    content: String,
    ext_mime: String,
}

#[derive(Deserialize)]
struct Prediction {
    #[serde(rename = "CTLabel")]
    ct_label: String,
    #[serde(rename = "MIMEType")]
    mime_type: String,
    #[serde(rename = "Score")]
    score: f64,
}

#[derive(Deserialize)]
struct Case {
    scenario: Scenario,
    available: bool,
    prediction: Option<Prediction>,
    prediction_log: Vec<String>,
    verify_log: Vec<String>,
    kind: String,
    detect_error: String,
    detect_stderr: String,
    transcript: Vec<String>,
}

#[derive(Deserialize)]
struct Fixture {
    schema_version: u32,
    script: String,
    cases: Vec<Case>,
    label_order: Vec<String>,
    label_to_mime: std::collections::BTreeMap<String, String>,
}

fn fixture() -> Fixture {
    use std::fs::read;
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testdata/port/ingest/magika.json");
    serde_json::from_slice(&read(path).unwrap()).unwrap()
}

fn b64(s: &str) -> Vec<u8> {
    use base64::{Engine, engine::general_purpose::STANDARD};
    STANDARD.decode(s).unwrap()
}

fn run(case: &Case, script: &str, root: &Path) -> Result<(), String> {
    let sc = &case.scenario;
    let tools = root.join("tools");
    let files = root.join("files");
    std::fs::create_dir_all(&tools).unwrap();
    std::fs::create_dir_all(&files).unwrap();
    let put = |name: &str, content: &str| std::fs::write(tools.join(name), content).unwrap();
    match sc.tool.as_str() {
        "ok" | "noexec" => {
            let magika = tools.join("magika");
            std::fs::write(&magika, script).unwrap();
            let mode = if sc.tool == "ok" { 0o700 } else { 0o600 };
            std::fs::set_permissions(&magika, std::fs::Permissions::from_mode(mode)).unwrap();
        }
        "dir" => std::fs::create_dir(tools.join("magika")).unwrap(),
        _ => {}
    }
    if !sc.stdout.is_empty() {
        put("stdout", &sc.stdout);
    }
    if !sc.stderr.is_empty() {
        put("stderr", &sc.stderr);
    }
    if sc.exit != 0 {
        put("exit", &sc.exit.to_string());
    }
    let path = files.join(&sc.file);
    std::fs::write(&path, b64(&sc.content)).unwrap();
    let path_text = path.to_string_lossy().into_owned();
    let dir = root.to_string_lossy().into_owned();
    let norm = |s: &str| s.replace(&dir, "$DIR");

    // SAFETY-free: tests are serialized by PATH_LOCK; set_var is process-global.
    let saved = std::env::var_os("PATH");
    // SAFETY: serialized by PATH_LOCK; no other thread reads the environment.
    unsafe { std::env::set_var("PATH", &tools) };
    #[allow(clippy::redundant_closure_call)]
    let result = (|| {
        let mut errors = Vec::new();
        if filetype::available() != case.available {
            errors.push(format!(
                "available {} != {}",
                filetype::available(),
                case.available
            ));
        }
        let mut logs = Vec::new();
        let got = filetype::detect(&path_text, &mut |m| logs.push(norm(&m)));
        let want = case.prediction.as_ref().map(|p| MagikaPrediction {
            ct_label: p.ct_label.clone(),
            mime_type: p.mime_type.clone(),
            score: p.score,
        });
        if got != want {
            errors.push(format!("prediction {got:?} != {want:?}"));
        }
        if logs != case.prediction_log {
            errors.push(format!(
                "prediction log {logs:?} != {:?}",
                case.prediction_log
            ));
        }
        let mut logs = Vec::new();
        filetype::verify_against_guess(&path_text, &sc.ext_mime, &mut |m| logs.push(norm(&m)));
        if logs != case.verify_log {
            errors.push(format!("verify log {logs:?} != {:?}", case.verify_log));
        }
        filetype::verify_against_guess(&path_text, &sc.ext_mime, &mut |_| {});
        let _ = std::fs::remove_file(tools.join("log"));
        let mut stderr = String::new();
        let detected = detect_file_with(&path_text, &mut |line| {
            stderr.push_str(&norm(&line));
            stderr.push('\n');
        });
        let (kind, error) = match detected {
            Ok(kind) => (kind, String::new()),
            Err(e) => (String::new(), norm(&e)),
        };
        if kind != case.kind || error != case.detect_error || stderr != case.detect_stderr {
            errors.push(format!(
                "detect ({kind:?}, {error:?}, {stderr:?}) != ({:?}, {:?}, {:?})",
                case.kind, case.detect_error, case.detect_stderr
            ));
        }
        let transcript = std::fs::read_to_string(tools.join("log"))
            .map(|t| {
                t.strip_suffix('\n')
                    .unwrap_or(&t)
                    .split('\n')
                    .map(&norm)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        if transcript != case.transcript {
            errors.push(format!(
                "transcript {transcript:?} != {:?}",
                case.transcript
            ));
        }
        if errors.is_empty() {
            Ok(())
        } else {
            Err(errors.join("; "))
        }
    })();
    // SAFETY: serialized by PATH_LOCK.
    unsafe {
        match saved {
            Some(v) => std::env::set_var("PATH", v),
            None => std::env::remove_var("PATH"),
        }
    }
    result
}

#[test]
fn magika_scenarios_replay_go() {
    let _guard = PATH_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let fx = fixture();
    assert_eq!(fx.schema_version, 1);
    assert_eq!(fx.cases.len(), 54, "magika fixture case count");
    let base = std::env::temp_dir().join(format!("ingest-magika-{}", std::process::id()));
    let mut failures = Vec::new();
    for (i, case) in fx.cases.iter().enumerate() {
        let root = base.join(i.to_string());
        if let Err(e) = run(case, &fx.script, &root) {
            failures.push(format!("{}: {e}", case.scenario.id));
        }
    }
    let _ = std::fs::remove_dir_all(&base);
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn label_table_replays_go() {
    let fx = fixture();
    assert!(fx.label_order.len() >= 20);
    for label in &fx.label_order {
        assert_eq!(
            filetype::label_to_mime(label),
            fx.label_to_mime[label],
            "label {label:?}"
        );
    }
}

#[test]
fn negative_control_mutated_prediction_is_rejected() {
    let _guard = PATH_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let fx = fixture();
    let case = fx
        .cases
        .iter()
        .find(|c| c.scenario.id == "mismatch-png-as-pdf")
        .unwrap();
    let mut mutated = Case {
        scenario: Scenario {
            ..clone_scenario(&case.scenario)
        },
        available: case.available,
        prediction: Some(Prediction {
            ct_label: "pdf".into(),
            mime_type: "application/pdf".into(),
            score: 0.5,
        }),
        prediction_log: case.prediction_log.clone(),
        verify_log: case.verify_log.clone(),
        kind: case.kind.clone(),
        detect_error: case.detect_error.clone(),
        detect_stderr: case.detect_stderr.clone(),
        transcript: case.transcript.clone(),
    };
    let base = std::env::temp_dir().join(format!("ingest-magika-neg-{}", std::process::id()));
    assert!(run(&mutated, &fx.script, &base.join("a")).is_err());
    mutated.detect_stderr.clear();
    assert!(run(&mutated, &fx.script, &base.join("b")).is_err());
    let _ = std::fs::remove_dir_all(&base);
}

fn clone_scenario(s: &Scenario) -> Scenario {
    Scenario {
        id: s.id.clone(),
        tool: s.tool.clone(),
        stdout: s.stdout.clone(),
        stderr: s.stderr.clone(),
        exit: s.exit,
        file: s.file.clone(),
        content: s.content.clone(),
        ext_mime: s.ext_mime.clone(),
    }
}
